create.example:
const { Vector3 } = kcds.math;

kcds.world.Area.create({
  id: 'town-gate',
  type: 'box',
  position: new Vector3(100, 200, 10),
  min: new Vector3(-5, -5, -2),
  max: new Vector3(5, 5, 4),
  labels: ['town'],
});

kcds.core.Events.on('areaEnter', (area, entity, matchingDimension) => {
  if (area.id === 'town-gate' && matchingDimension) {
    console.info(`entered: ${entity.id}`);
  }
});

create.exampleCs:
Area.Create(new { id = "town-gate", type = "box", position = new Vector3(100, 200, 10), min = new Vector3(-5, -5, -2), max = new Vector3(5, 5, 4), labels = new[] { "town" } });

Events.On("areaEnter", (Area area, Entity entity, JsValue matchingDimension) =>
{
    if (area.Id == "town-gate" && matchingDimension)
    {
        Log.Info($"entered: {entity.Id}");
    }
});

