aroundEntity.example:
kcds.core.Events.on('playerCommand', (player, command) => {
  if (command !== 'where') {
    return;
  }
  const names = kcds.world.Area.aroundEntity(player).map((area) => area.name);
  kcds.core.Chat.sendToPlayer(player, names.join(', ') || 'nowhere in particular');
});

aroundEntity.exampleCs:
Events.On("playerCommand", (Player player, string command) =>
{
    if (command != "where")
    {
        return;
    }
    var names = Area.AroundEntity(player).Select(area => area.Name).ToArray();
    Chat.SendToPlayer(player, (string.IsNullOrEmpty(string.Join(", ", names)) ? "nowhere in particular" : string.Join(", ", names)));
});

