metadata.exampleCs:
var stall = Area.GetById("market-stall");
var metadata = new Dictionary<string, object?>();
foreach (var key in stall.Metadata.Keys)
{
    metadata[key] = stall.Metadata[key];
}
metadata["owner"] = player.Nickname;
stall.AsValue().Set("metadata", metadata);

